-- Touchline — 0014: "Club business" (phase 3): stadium & tickets, fan mood, sponsors with clauses, staff, board
-- confidence and budgets (economy-v2 / business-v1). Additive; the ledger type list is widened (superset).
-- Offers and candidates are generated by the server; user commands only pick among stored rows.

alter table public.club_ledger drop constraint if exists club_ledger_event_type_check;
alter table public.club_ledger add constraint club_ledger_event_type_check check (event_type in (
  'initial_balance','transfer_sale','transfer_purchase','gate_receipts','sponsorship',
  'wages','prize_money','result_bonus','adjustment','staff_wages','infrastructure'));

-- ------------------------------------------------------------------ tables
create table if not exists public.club_business (
  club_id       uuid primary key references public.game_clubs(id) on delete cascade,
  game_id       uuid not null references public.games(id) on delete cascade,
  fan_mood      smallint not null default 50 check (fan_mood between 0 and 100),
  ticket_price  text not null default 'normal' check (ticket_price in ('low','normal','high')),
  base_capacity integer not null check (base_capacity > 0),
  upgrades      jsonb not null default '[]'::jsonb,
  updated_at    timestamptz not null default now()
);

create table if not exists public.club_staff (
  id           uuid primary key default gen_random_uuid(),
  game_id      uuid not null references public.games(id) on delete cascade,
  club_id      uuid not null references public.game_clubs(id) on delete cascade,
  role         text not null check (role in ('assistant','fitness','medical','scout','youth')),
  name         text not null,
  level        smallint not null check (level between 1 and 5),
  wage_cents   bigint not null check (wage_cents >= 0),
  hired_season integer not null,
  active       boolean not null default true,
  left_at      timestamptz,
  created_at   timestamptz not null default now()
);
create unique index if not exists club_staff_active_role on public.club_staff(club_id, role) where active;

create table if not exists public.staff_candidates (
  id         uuid primary key default gen_random_uuid(),
  game_id    uuid not null references public.games(id) on delete cascade,
  club_id    uuid not null references public.game_clubs(id) on delete cascade,
  season     integer not null,
  role       text not null check (role in ('assistant','fitness','medical','scout','youth')),
  name       text not null,
  level      smallint not null check (level between 1 and 5),
  wage_cents bigint not null check (wage_cents >= 0),
  taken      boolean not null default false,
  unique (club_id, season, role, name)
);

create table if not exists public.sponsor_offers (
  id              uuid primary key default gen_random_uuid(),
  game_id         uuid not null references public.games(id) on delete cascade,
  club_id         uuid not null references public.game_clubs(id) on delete cascade,
  season          integer not null,
  slot            text not null check (slot in ('main','sleeve','stadium','kit')),
  brand           text not null,
  kind            text not null check (kind in ('fixed','balanced','performance')),
  base_cents      bigint not null check (base_cents >= 0),
  win_bonus_cents bigint not null default 0 check (win_bonus_cents >= 0),
  clause          jsonb,
  seasons         smallint not null check (seasons between 1 and 3),
  deadline_round  integer not null,
  status          text not null default 'open' check (status in ('open','signed','declined','expired')),
  created_at      timestamptz not null default now(),
  unique (club_id, season, slot, brand)
);

create table if not exists public.sponsor_deals (
  id              uuid primary key default gen_random_uuid(),
  game_id         uuid not null references public.games(id) on delete cascade,
  club_id         uuid not null references public.game_clubs(id) on delete cascade,
  offer_id        uuid references public.sponsor_offers(id) on delete set null,
  slot            text not null check (slot in ('main','sleeve','stadium','kit')),
  brand           text not null,
  kind            text not null,
  base_cents      bigint not null,
  win_bonus_cents bigint not null default 0,
  clause          jsonb,
  start_season    integer not null,
  end_season      integer not null,
  signed_by       text not null default 'manager' check (signed_by in ('manager','default','ai')),
  created_at      timestamptz not null default now()
);
create unique index if not exists sponsor_deals_slot_season on public.sponsor_deals(club_id, slot, start_season);

create table if not exists public.board_state (
  club_id               uuid not null references public.game_clubs(id) on delete cascade,
  season                integer not null,
  game_id               uuid not null references public.games(id) on delete cascade,
  objective             jsonb not null,
  confidence            smallint not null default 60 check (confidence between 0 and 100),
  base_transfer_cents   bigint not null default 0,
  base_wage_cents       bigint not null default 0,
  shift_pct             smallint not null default 0 check (shift_pct between -20 and 20),
  flags                 jsonb not null default '{}'::jsonb,
  history               jsonb not null default '[]'::jsonb,
  final_position        integer,
  updated_at            timestamptz not null default now(),
  primary key (club_id, season)
);

do $$
declare t text;
begin
  foreach t in array array['club_business','club_staff','staff_candidates','sponsor_offers','sponsor_deals','board_state'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
    execute format('grant select on public.%I to authenticated', t);
  end loop;
end $$;
-- stadium, staff and signed sponsors are public within the league; offers, candidates and the board are private
create policy member_read on public.club_business for select to authenticated using (public.is_game_member(game_id));
create policy member_read on public.club_staff for select to authenticated using (public.is_game_member(game_id));
create policy member_read on public.sponsor_deals for select to authenticated using (public.is_game_member(game_id));
create policy own_club_read on public.staff_candidates for select to authenticated using (public.manages_club(club_id));
create policy own_club_read on public.sponsor_offers for select to authenticated using (public.manages_club(club_id));
create policy own_club_read on public.board_state for select to authenticated using (public.manages_club(club_id));

-- ------------------------------------------------------------------ user commands
create or replace function public._my_active_club(p_game_id uuid) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_club uuid := public.my_club_id(p_game_id); v_game public.games;
begin
  if v_club is null then perform public._fail('no_club', 'Não geres nenhum clube nesta liga.'); end if;
  select * into v_game from public.games where id = p_game_id;
  if v_game.status <> 'active' then perform public._fail('not_active', 'A liga ainda não começou.'); end if;
  if public._game_is_processing(v_game) then perform public._fail('processing', 'Jornada em processamento.'); end if;
  return v_club;
end $$;

create or replace function public.set_ticket_price(p_game_id uuid, p_level text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_club uuid := public._my_active_club(p_game_id);
begin
  if p_level not in ('low','normal','high') then perform public._fail('invalid', 'Preço inválido.'); end if;
  update public.club_business set ticket_price = p_level, updated_at = now() where club_id = v_club;
  if not found then perform public._fail('not_ready', 'O estádio ainda não está configurado.'); end if;
end $$;

-- costs/durations mirror UPGRADES in src/engine/economy/business.ts
create or replace function public.start_upgrade(p_game_id uuid, p_kind text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_club uuid := public._my_active_club(p_game_id); v_game public.games; v_b public.club_business; v_c public.game_clubs;
        v_cost bigint; v_rounds int; v_max int; v_ready int; v_n int;
begin
  select * into v_game from public.games where id = p_game_id;
  select * into v_b from public.club_business where club_id = v_club for update;
  if not found then perform public._fail('not_ready', 'O estádio ainda não está configurado.'); end if;
  case p_kind
    when 'capacity' then v_cost := 300000000; v_rounds := 6; v_max := 5;
    when 'vip' then v_cost := 200000000; v_rounds := 8; v_max := 3;
    else perform public._fail('invalid', 'Obra inválida.');
  end case;
  select count(*) into v_n from jsonb_array_elements(v_b.upgrades) u where u->>'kind' = p_kind;
  if v_n >= v_max then perform public._fail('max', 'Já fizeste todas as obras deste tipo.'); end if;
  if exists (select 1 from jsonb_array_elements(v_b.upgrades) u
              where (u->>'ready_at')::int > v_game.current_season * 100 + v_game.current_matchday) then
    perform public._fail('busy', 'Já há uma obra em curso.');
  end if;
  select * into v_c from public.game_clubs where id = v_club for update;
  if v_c.cash_cents - v_c.reserved_cents < v_cost then perform public._fail('funds', 'Saldo insuficiente para esta obra.'); end if;
  v_ready := v_game.current_season * 100 + v_game.current_matchday + v_rounds;
  perform public._ledger(p_game_id, v_club, 'infrastructure', -v_cost, p_kind,
                         'upgrade:' || v_club || ':' || p_kind || ':' || (v_n + 1), v_game.current_season, v_game.current_matchday);
  update public.club_business set upgrades = upgrades || jsonb_build_array(jsonb_build_object('kind', p_kind, 'ready_at', v_ready)), updated_at = now()
   where club_id = v_club;
  perform public._audit(p_game_id, auth.uid(), 'club.upgrade', 'club', v_club::text, jsonb_build_object('kind', p_kind, 'cost_cents', v_cost));
  return jsonb_build_object('ready_at', v_ready);
end $$;

-- replacing a staff member costs 2 rounds of the outgoing wage (compensation)
create or replace function public.hire_staff(p_candidate_id uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_c public.staff_candidates; v_game public.games; v_old public.club_staff; v_club uuid;
begin
  select * into v_c from public.staff_candidates where id = p_candidate_id for update;
  if not found or not public.manages_club(v_c.club_id) then perform public._fail('not_found', 'Candidato inexistente.'); end if;
  v_club := public._my_active_club(v_c.game_id);
  select * into v_game from public.games where id = v_c.game_id;
  if v_c.taken or v_c.season <> v_game.current_season then perform public._fail('unavailable', 'Este candidato já não está disponível.'); end if;
  select * into v_old from public.club_staff where club_id = v_club and role = v_c.role and active for update;
  if found then
    if v_old.wage_cents > 0 then
      perform public._ledger(v_c.game_id, v_club, 'staff_wages', -2 * v_old.wage_cents, v_old.id::text,
                             'staff:fire:' || v_old.id, v_game.current_season, v_game.current_matchday);
    end if;
    update public.club_staff set active = false, left_at = now() where id = v_old.id;
  end if;
  insert into public.club_staff (game_id, club_id, role, name, level, wage_cents, hired_season)
  values (v_c.game_id, v_club, v_c.role, v_c.name, v_c.level, v_c.wage_cents, v_game.current_season);
  update public.staff_candidates set taken = true where id = v_c.id;
  perform public._audit(v_c.game_id, auth.uid(), 'staff.hire', 'staff', v_c.id::text, jsonb_build_object('role', v_c.role, 'level', v_c.level));
  return jsonb_build_object('role', v_c.role, 'level', v_c.level, 'compensation_cents', coalesce(2 * v_old.wage_cents, 0));
end $$;

create or replace function public.sign_sponsor(p_offer_id uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_o public.sponsor_offers; v_game public.games; v_club uuid;
begin
  select * into v_o from public.sponsor_offers where id = p_offer_id for update;
  if not found or not public.manages_club(v_o.club_id) then perform public._fail('not_found', 'Proposta inexistente.'); end if;
  v_club := public._my_active_club(v_o.game_id);
  select * into v_game from public.games where id = v_o.game_id;
  if v_o.status <> 'open' or v_o.season <> v_game.current_season then perform public._fail('unavailable', 'Esta proposta já não está disponível.'); end if;
  if exists (select 1 from public.sponsor_deals where club_id = v_club and slot = v_o.slot
              and start_season <= v_game.current_season and end_season >= v_game.current_season) then
    perform public._fail('taken', 'Já tens um patrocinador neste espaço.');
  end if;
  insert into public.sponsor_deals (game_id, club_id, offer_id, slot, brand, kind, base_cents, win_bonus_cents, clause, start_season, end_season, signed_by)
  values (v_o.game_id, v_club, v_o.id, v_o.slot, v_o.brand, v_o.kind, v_o.base_cents, v_o.win_bonus_cents, v_o.clause,
          v_game.current_season, v_game.current_season + v_o.seasons - 1, 'manager');
  update public.sponsor_offers set status = case when id = v_o.id then 'signed' else 'declined' end
   where club_id = v_club and season = v_o.season and slot = v_o.slot and status = 'open';
  perform public._audit(v_o.game_id, auth.uid(), 'sponsor.sign', 'sponsor_offer', v_o.id::text, jsonb_build_object('slot', v_o.slot, 'brand', v_o.brand));
  return jsonb_build_object('slot', v_o.slot, 'brand', v_o.brand);
end $$;

-- move up to 20% of the transfer budget into/out of the wage budget, only in the first 3 rounds of a season
create or replace function public.set_budget_shift(p_game_id uuid, p_shift integer) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_club uuid := public._my_active_club(p_game_id); v_game public.games;
begin
  select * into v_game from public.games where id = p_game_id;
  if p_shift is null or p_shift not between -20 and 20 then perform public._fail('invalid', 'Só podes mover até 20%.'); end if;
  if v_game.current_matchday > 3 then perform public._fail('late', 'O orçamento só pode ser ajustado nas 3 primeiras jornadas.'); end if;
  update public.board_state set shift_pct = p_shift, updated_at = now() where club_id = v_club and season = v_game.current_season;
  if not found then perform public._fail('not_ready', 'A direção ainda não definiu o orçamento.'); end if;
end $$;

-- ------------------------------------------------------------------ effects (adds confidence / fan_mood / ticket_price)
create or replace function public._apply_effects(p_game_id uuid, p_club_id uuid, p_effects jsonb, p_key text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare e jsonb; v_game public.games; v_pid uuid; v_d numeric;
begin
  select * into v_game from public.games where id = p_game_id;
  if p_effects is null or jsonb_typeof(p_effects) <> 'array' then return; end if;
  for e in select * from jsonb_array_elements(p_effects) loop
    v_pid := nullif(e->>'player_id', '')::uuid;
    if v_pid is not null and not exists (select 1 from public.game_players where id = v_pid and club_id = p_club_id) then
      continue;
    end if;
    v_d := coalesce((e->>'delta')::numeric, 0);
    case e->>'type'
      when 'morale' then
        update public.game_players set morale = greatest(0, least(100, morale + greatest(-20, least(20, v_d))::int)), version = version + 1, updated_at = now()
         where club_id = p_club_id and (v_pid is null and e->>'scope' = 'squad' or id = v_pid);
      when 'fitness' then
        update public.game_players set fitness = greatest(0, least(100, fitness + greatest(-30, least(30, v_d))::int)), version = version + 1, updated_at = now()
         where id = v_pid;
      when 'form' then
        update public.game_players set form = greatest(-3, least(3, form + greatest(-1.5, least(1.5, v_d)))), version = version + 1, updated_at = now()
         where id = v_pid;
      when 'injury' then
        update public.game_players set injured_matches = greatest(injured_matches, greatest(0, least(6, (e->>'matches')::int))),
               injury_type = coalesce(injury_type, 'Lesão'), version = version + 1, updated_at = now() where id = v_pid;
      when 'unavailable' then
        update public.game_players set suspension_matches = greatest(suspension_matches, greatest(0, least(3, (e->>'matches')::int))),
               version = version + 1, updated_at = now() where id = v_pid;
      when 'cash' then
        if abs(coalesce((e->>'delta_cents')::bigint, 0)) between 1 and 1000000000 then
          perform public._ledger(p_game_id, p_club_id, 'adjustment', (e->>'delta_cents')::bigint, p_key,
                                 p_key || ':cash', v_game.current_season, v_game.current_matchday);
        end if;
      when 'confidence' then
        update public.board_state set confidence = greatest(0, least(100, confidence + greatest(-15, least(15, v_d))::int)),
               history = history || jsonb_build_array(jsonb_build_object('round', v_game.current_matchday, 'delta', greatest(-15, least(15, v_d))::int, 'reason', coalesce(e->>'reason', 'Decisão no Gabinete'))),
               updated_at = now()
         where club_id = p_club_id and season = v_game.current_season;
      when 'fan_mood' then
        update public.club_business set fan_mood = greatest(0, least(100, fan_mood + greatest(-15, least(15, v_d))::int)), updated_at = now()
         where club_id = p_club_id;
      when 'ticket_price' then
        if e->>'level' in ('low','normal','high') then
          update public.club_business set ticket_price = e->>'level', updated_at = now() where club_id = p_club_id;
        end if;
      else null;
    end case;
  end loop;
end $$;

-- ------------------------------------------------------------------ grants
revoke all on function public._my_active_club(uuid) from public, anon, authenticated;
do $$
declare f text;
begin
  foreach f in array array['set_ticket_price(uuid, text)', 'start_upgrade(uuid, text)', 'hire_staff(uuid)',
                           'sign_sponsor(uuid)', 'set_budget_shift(uuid, integer)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated, service_role', f);
  end loop;
end $$;
